actions.script:
const support=ec.resource.script('component://mr-pass/screen/Support/Support.js')
query=support.param('q');statusCategory=support.param('statusCategory') || 'all';customerPartyId=support.param('customerPartyId')
cursor=support.param('cursor')
const found=siteInfo.authenticated ? support.portal.attempt('findCustomerCases',{siteId:resolvedSiteId,query,statusCategory,customerPartyId,cursor}) : {result:null}
view=found.result || null
// the next page's and the first page's addresses (the list's opaque cursor, design-forum §4.3)
const filters={q:query,statusCategory:statusCategory === 'all' ? null : statusCategory,customerPartyId}
nextHref=view?.nextCursor ? publicPath + support.query(Object.assign({},filters,{cursor:view.nextCursor})) : null
firstHref=cursor ? publicPath + support.query(filters) : null
failure=found.error || null
flash=support.take()
